/* 911: The Last Call — site app (vanilla JS, static GitHub Pages)
 * Data sources (all in this repo):
 *   data/team.json              members
 *   data/tasks.json             roadmap tasks + owners (generated by scripts/build_tasks.py)
 *   data/progress/<id>.json     each member's status/notes/log (updated by their AI)
 *   data/ideas.json             curated ideas
 *   GitHub Issues ("[فكرة]" / label idea)   ideas submitted from the site
 */
(() => {
  "use strict";

  const REPO = "AdnanMohammed0/911-The-Last-Call";
  const BRANCH = "main";
  const DATA_BASE = location.protocol === "file:" ? `https://raw.githubusercontent.com/${REPO}/${BRANCH}/` : "";
  const IDEA_PREFIX = "[فكرة]";
  const STORE_KEY = "911tlc.site.v2";

  const STATUSES = [
    { id: "backlog",  label: "بالانتظار" },
    { id: "progress", label: "قيد العمل" },
    { id: "testing",  label: "اختبار" },
    { id: "blocked",  label: "متوقفة" },
    { id: "done",     label: "مكتملة" },
  ];
  const STATUS = Object.fromEntries(STATUSES.map(s => [s.id, s]));

  const CATS = { NET: "الشبكات", GAME: "اللعب", AUDIO: "الصوت", AI: "الذكاء الاصطناعي", UI: "الواجهات", ART: "الفن" };

  const PHASES = [
    { id: 1, name: "النموذج الأولي والشبكات", en: "Core Prototype & Networking", weeks: "الأسابيع 1–6",   milestone: "M1 · Four On The Line" },
    { id: 2, name: "غرفة العمليات والحوارات", en: "Dispatch & Dialogue Engine",  weeks: "الأسابيع 7–12",  milestone: "M2 · Is This A Prank?" },
    { id: 3, name: "الميدان والذكاء الاصطناعي", en: "Field Gameplay & AI",       weeks: "الأسابيع 13–22", milestone: "M3 · Vertical Slice" },
    { id: 4, name: "العواقب والصقل",          en: "Consequence Matrix & Polish", weeks: "الأسابيع 23–30", milestone: "M4 · Content Complete" },
    { id: 5, name: "الإطلاق على Steam",       en: "Steam Release",               weeks: "الأسابيع 31–36", milestone: "M5 · The Last Call" },
  ];

  const IDEA_CATS = {
    mission:  { label: "مهمة / سيناريو", color: "#f59e0b" },
    horror:   { label: "رعب / كيان",     color: "#a78bfa" },
    mechanic: { label: "ميكانيك لعب",    color: "#06b6d4" },
    story:    { label: "قصة",            color: "#ef4444" },
    tech:     { label: "تقنية",          color: "#22c55e" },
    art:      { label: "فن / صوت",       color: "#f472b6" },
    other:    { label: "أخرى",           color: "#8d99aa" },
  };
  const IDEA_STATUS = { new: "جديدة", approved: "معتمدة", "in-roadmap": "بالخطة", rejected: "مرفوضة", open: "مفتوحة", closed: "مغلقة" };

  /* ---------------- state ---------------- */
  const S = {
    team: [], members: {}, tasks: [], progress: {}, ideas: [], issues: [], issuesError: false,
    ui: loadUI(),
  };

  function loadUI() {
    const d = { member: "all", cats: [], phase: "all", q: "", ideaCat: "all" };
    try { return { ...d, ...JSON.parse(localStorage.getItem(STORE_KEY) || "{}") }; } catch { return d; }
  }
  function saveUI() { try { localStorage.setItem(STORE_KEY, JSON.stringify(S.ui)); } catch { /* storage unavailable */ } }

  /* ---------------- helpers ---------------- */
  const $ = s => document.querySelector(s);
  function h(tag, attrs = {}, ...kids) {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v == null || v === false) continue;
      if (k === "class") n.className = v;
      else if (k === "style") n.style.cssText = v;
      else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v === true ? "" : v);
    }
    for (const kid of kids.flat(Infinity)) if (kid != null && kid !== false) n.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
    return n;
  }
  const pct = (a, b) => (b ? Math.round((a / b) * 100) : 0);
  const ghBlob = path => `https://github.com/${REPO}/blob/${BRANCH}/${path}`;
  const byId = (a, b) => a.id.localeCompare(b.id, "en", { numeric: true });

  let toastT;
  function toast(msg) {
    const t = $("#toast");
    t.textContent = msg;
    t.classList.add("show");
    clearTimeout(toastT);
    toastT = setTimeout(() => t.classList.remove("show"), 2000);
  }

  async function copy(text) {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      const ta = h("textarea", { style: "position:fixed;opacity:0" });
      ta.value = text;
      document.body.append(ta);
      ta.select();
      document.execCommand("copy");
      ta.remove();
    }
    toast("تم النسخ ✓");
  }

  async function getJSON(path) {
    const res = await fetch(DATA_BASE + path, { cache: "no-store" });
    if (!res.ok) throw new Error(`${path}: ${res.status}`);
    return res.json();
  }

  function avatar(m, size = "") {
    const initials = (m?.name || "?").trim().slice(0, 1).toUpperCase();
    const el = h("span", { class: `avatar ${size}`, style: `--c:${m?.color || "#8d99aa"}`, title: m?.name || "" }, initials);
    if (m?.github) {
      const img = h("img", { src: `https://github.com/${m.github}.png?size=96`, alt: "", loading: "lazy" });
      img.addEventListener("error", () => img.remove());
      img.addEventListener("load", () => { el.firstChild?.nodeType === 3 && el.firstChild.remove(); });
      el.append(img);
    }
    return el;
  }

  /* ---------------- data model ---------------- */
  function taskState(t) {
    // Owner's entry wins unless another member updated it more recently (helping out).
    let best = null;
    for (const [mid, p] of Object.entries(S.progress)) {
      const e = p?.tasks?.[t.id];
      if (!e || !STATUS[e.status]) continue;
      const cand = { ...e, by: mid };
      if (!best || (e.updated_at || "") > (best.updated_at || "") || ((e.updated_at || "") === (best.updated_at || "") && mid === t.owner)) best = cand;
    }
    return best || { status: "backlog" };
  }
  const statusOf = t => taskState(t).status;

  function stats(list) {
    const c = Object.fromEntries(STATUSES.map(s => [s.id, 0]));
    list.forEach(t => c[statusOf(t)]++);
    return { ...c, total: list.length, pct: pct(c.done, list.length) };
  }

  function allLogs() {
    const out = [];
    for (const [mid, p] of Object.entries(S.progress)) {
      (p?.log || []).forEach((e, i) => out.push({ ...e, member: mid, _i: i }));
    }
    return out.sort((a, b) => (b.date || "").localeCompare(a.date || "") || b._i - a._i);
  }

  function activePhase() {
    return PHASES.find(ph => {
      const s = stats(S.tasks.filter(t => t.phase === ph.id));
      return s.total && s.done < s.total;
    });
  }

  /* ---------------- prompts ---------------- */
  const startPrompt = m =>
    `أنا ${m.name} (${m.id}). اقرأ AGENTS.md و ${m.prompt_file} و data/progress/${m.id}.json.\n` +
    `لخّصلي وين وصلت، وشنو المهام اللي أعتمد عليها من باقي الفريق، واقترح المهمة الجاية.\n` +
    `كل ما تخلص شغل: سجّل التقدم تلقائياً بـ data/progress/${m.id}.json وارفعه على GitHub (commit + push) بدون ما أطلب وبدون أي توقيع AI.`;

  const taskPrompt = t => {
    const m = S.members[t.owner];
    return `أنا ${m?.name || t.owner} (${t.owner}). اقرأ AGENTS.md و prompts/${t.owner}.md.\n` +
      `اشتغل على المهمة ${t.id}: ${t.title}\n` +
      `(${PHASES[t.phase - 1].en} › ${t.group} · ${t.cat}).\n` +
      `ارجع للوثائق بـ docs/ حسب الحاجة. لما تخلص سجّل التقدم تلقائياً بـ data/progress/${t.owner}.json وارفعه على GitHub.`;
  };

  const updatePrompt = (t, status = "done") =>
    `حدّث تقدمي: المهمة ${t.id} صارت ${status}. الملاحظة: <اكتب شنو صار>.\n` +
    `سجّلها بـ data/progress/${t.owner}.json مع log لليوم، شغّل python scripts/validate_progress.py، وسوّي commit و push.`;

  /* ---------------- router ---------------- */
  const VIEWS = ["home", "team", "board", "roadmap", "story", "game", "ideas", "prompts"];
  function route() {
    const v = VIEWS.includes(location.hash.slice(1)) ? location.hash.slice(1) : "home";
    document.querySelectorAll(".view").forEach(sec => { sec.hidden = sec.id !== `view-${v}`; });
    document.querySelectorAll(".tabs a").forEach(a => { if (a.dataset.view === v) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); });
    const sec = $(`#view-${v}`);
    document.title = `${sec.dataset.title} — 911: The Last Call`;
    const tabs = $(".tabs"), cur = $(`.tabs a[data-view="${v}"]`);
    if (cur && tabs.scrollWidth > tabs.clientWidth) tabs.scrollLeft += cur.getBoundingClientRect().left - tabs.getBoundingClientRect().left - 16;
    window.scrollTo(0, 0);
  }

  /* ---------------- render: home ---------------- */
  function renderHome() {
    const s = stats(S.tasks);
    $("#ovPct").textContent = s.pct + "%";
    $("#ringFg").style.strokeDashoffset = String(326.7 * (1 - s.pct / 100));
    $("#ovDone").textContent = s.done;
    $("#ovActive").textContent = s.progress + s.testing;
    $("#ovTotal").textContent = s.total;
    const ap = activePhase();
    $("#ovPhase").replaceChildren(ap
      ? h("span", {}, "المرحلة الحالية: ", h("b", {}, `${ap.id} · ${ap.name}`))
      : h("b", {}, "كل المراحل مكتملة 🎉"));

    $("#teamStrip").replaceChildren(...S.team.map(m => {
      const ms = stats(S.tasks.filter(t => t.owner === m.id));
      return h("a", { class: "panel member-mini", href: "#team", style: `--c:${m.color}` },
        avatar(m),
        h("div", {},
          h("h3", {}, m.name),
          h("p", {}, m.role),
          h("div", { class: "bar" }, h("i", { style: `width:${ms.pct}%;background:${m.color}` }))),
        h("span", { class: "pct" }, ms.pct + "%"));
    }));

    renderFeed($("#homeFeed"), allLogs().slice(0, 12));

    $("#homePhases").replaceChildren(...PHASES.map(ph => {
      const ps = stats(S.tasks.filter(t => t.phase === ph.id));
      return h("div", { class: "row" },
        h("span", {}, `المرحلة ${ph.id}`),
        stackedBar(ph.id),
        h("span", {}, ps.pct + "%"));
    }));
  }

  function renderFeed(el, logs) {
    if (!logs.length) { el.replaceChildren(h("li", { class: "empty", style: "display:block" }, "ماكو نشاط مسجّل بعد.")); return; }
    el.replaceChildren(...logs.map(e => {
      const m = S.members[e.member];
      return h("li", {},
        avatar(m, ""),
        h("div", {},
          h("div", { class: "feed-head" },
            h("span", { class: "who", style: `color:${m?.color}` }, m?.name || e.member),
            h("time", { datetime: e.date }, e.date)),
          h("p", {}, e.summary),
          e.tasks?.length ? h("div", { class: "tids" }, e.tasks.map(tid => h("button", { class: "tid", type: "button", onclick: () => openTask(tid) }, tid))) : null));
    }));
  }

  function stackedBar(phaseId, big = false) {
    const list = S.tasks.filter(t => t.phase === phaseId);
    return h("div", { class: `bar${big ? " lg" : ""}`, role: "img", "aria-label": `إنجاز المرحلة ${phaseId}: ${stats(list).pct}%` },
      S.team.map(m => {
        const d = list.filter(t => t.owner === m.id && statusOf(t) === "done").length;
        return h("i", { style: `width:${pct(d, list.length)}%;background:${m.color}`, title: `${m.name}: ${d}` });
      }));
  }

  /* ---------------- render: team ---------------- */
  function renderTeam() {
    $("#members").replaceChildren(...S.team.map(m => {
      const mine = S.tasks.filter(t => t.owner === m.id).sort(byId);
      const s = stats(mine);
      const current = mine.filter(t => ["progress", "testing", "blocked"].includes(statusOf(t)));
      const next = mine.filter(t => statusOf(t) === "backlog").slice(0, 3);
      const logs = (S.progress[m.id]?.log || []).slice(-5).reverse();
      const updated = S.progress[m.id]?.updated_at;

      return h("article", { class: "panel member", style: `--c:${m.color}` },
        h("div", { class: "member-head" },
          avatar(m, "lg"),
          h("div", {},
            h("h2", {}, m.name),
            m.github ? h("a", { href: `https://github.com/${m.github}`, target: "_blank", rel: "noopener" }, "@" + m.github) : null)),
        h("p", { class: "role" }, m.role),
        h("div", {},
          h("div", { class: "big" }, h("b", {}, s.pct + "%"), h("span", {}, `${s.done} من ${s.total} مهمة`)),
          h("div", { class: "bar lg" }, h("i", { style: `width:${s.pct}%;background:${m.color}` }))),
        h("div", { class: "st-counts" }, STATUSES.map(st =>
          h("div", { style: `--s:var(--st-${st.id})` }, h("b", {}, s[st.id]), h("small", {}, st.label)))),
        h("div", {},
          h("h3", {}, current.length ? "يشتغل عليها هسه" : "المهام الجاية"),
          taskList(current.length ? current : next)),
        h("div", {},
          h("h3", {}, "سجل الإنجازات", updated ? h("span", { class: "mono", style: "color:var(--faint);font-weight:400" }, ` · ${updated}`) : null),
          logs.length
            ? h("ul", { class: "log" }, logs.map(e => h("li", {}, h("time", {}, e.date), e.summary)))
            : h("p", { class: "empty", style: "padding:10px" }, "ماكو سجل بعد.")),
        h("div", { class: "member-actions" },
          h("button", { class: "btn small", type: "button", onclick: () => { S.ui.member = m.id; saveUI(); location.hash = "board"; renderBoard(); } }, "كل مهامه"),
          h("button", { class: "btn small", type: "button", onclick: () => copy(startPrompt(m)) }, "نسخ برومبت البداية"),
          h("a", { class: "btn small", href: ghBlob(m.prompt_file), target: "_blank", rel: "noopener" }, "ملف البرومبت")));
    }));

    $("#contrib").replaceChildren(
      ...PHASES.map(ph => {
        const list = S.tasks.filter(t => t.phase === ph.id);
        const s = stats(list);
        return h("div", { class: "row" }, h("span", {}, `${ph.id} · ${ph.name}`), stackedBar(ph.id, true), h("span", {}, `${s.done}/${s.total}`));
      }),
      h("div", { class: "legend" }, S.team.map(m => h("span", {}, h("i", { class: "dot", style: `background:${m.color}` }), m.name))));
  }

  function taskList(list) {
    if (!list.length) return h("p", { class: "empty", style: "padding:10px" }, "كل المهام مكتملة ✓");
    return h("ul", { class: "task-list" }, list.map(t => {
      const st = statusOf(t);
      return h("li", {}, h("button", { type: "button", onclick: () => openTask(t.id), title: STATUS[st].label },
        h("span", { class: "sdot", style: `--s:var(--st-${st})` }),
        h("span", { class: "mono", style: "font-size:12px;color:var(--muted)" }, t.id),
        h("span", { class: "t" }, t.title)));
    }));
  }

  /* ---------------- render: board ---------------- */
  function renderFilters() {
    const ui = S.ui;
    $("#memberChips").replaceChildren(
      h("button", { class: "chip", type: "button", "aria-pressed": String(ui.member === "all"), onclick: () => setUI({ member: "all" }) }, "كل الفريق"),
      ...S.team.map(m => h("button", {
        class: "chip", type: "button", style: `--c:${m.color}`, "aria-pressed": String(ui.member === m.id),
        onclick: () => setUI({ member: ui.member === m.id ? "all" : m.id }),
      }, avatar(m, "sm"), m.name)));

    $("#catChips").replaceChildren(
      h("button", { class: "chip", type: "button", "aria-pressed": String(!ui.cats.length), onclick: () => setUI({ cats: [] }) }, "كل الأقسام"),
      ...Object.entries(CATS).map(([k, label]) => {
        const on = ui.cats.includes(k);
        return h("button", {
          class: "chip", type: "button", style: `--c:var(--cat-${k})`, "aria-pressed": String(on),
          onclick: () => setUI({ cats: on ? ui.cats.filter(c => c !== k) : [...ui.cats, k] }),
        }, label);
      }));

    $("#phaseSel").value = ui.phase;
    if ($("#searchBox").value !== ui.q) $("#searchBox").value = ui.q;
  }

  function setUI(patch) { Object.assign(S.ui, patch); saveUI(); renderBoard(); }

  function visibleTasks() {
    const { member, cats, phase, q } = S.ui;
    const qq = q.trim().toLowerCase();
    return S.tasks.filter(t =>
      (member === "all" || t.owner === member) &&
      (!cats.length || cats.includes(t.cat)) &&
      (phase === "all" || String(t.phase) === phase) &&
      (!qq || t.id.toLowerCase().includes(qq) || t.title.toLowerCase().includes(qq) || t.group.toLowerCase().includes(qq)));
  }

  function renderBoard() {
    renderFilters();
    const list = visibleTasks().sort(byId);
    $("#board").replaceChildren(...STATUSES.map(st => {
      const items = list.filter(t => statusOf(t) === st.id);
      return h("div", { class: "panel col" },
        h("div", { class: "col-head" },
          h("i", { class: "dot", style: `background:var(--st-${st.id});box-shadow:0 0 8px var(--st-${st.id})` }),
          st.label, h("span", { class: "count" }, items.length)),
        h("div", { class: "col-body" }, items.length ? items.map(card) : h("div", { class: "empty" }, "—")));
    }));
  }

  function card(t) {
    const m = S.members[t.owner];
    const ts = taskState(t);
    return h("button", { class: "card", type: "button", style: `--c:var(--cat-${t.cat})`, onclick: () => openTask(t.id) },
      h("div", { class: "meta" }, h("span", { class: "tag" }, t.cat), h("span", {}, t.id), h("span", {}, `P${t.phase}`), avatar(m, "sm")),
      h("p", { class: "title" }, t.title),
      ts.note ? h("p", { class: "note" }, ts.note) : null);
  }

  /* ---------------- render: roadmap ---------------- */
  function renderRoadmap() {
    const ap = activePhase();
    $("#phases").replaceChildren(...PHASES.map(ph => {
      const list = S.tasks.filter(t => t.phase === ph.id).sort(byId);
      const s = stats(list);
      const groups = [...new Set(list.map(t => t.group))];
      return h("details", { class: "panel phase", open: ap?.id === ph.id },
        h("summary", {},
          h("div", {},
            h("h2", {}, `المرحلة ${ph.id} — ${ph.name}`,
              s.done === s.total && s.total ? h("span", { class: "badge done" }, "DONE") : ap?.id === ph.id ? h("span", { class: "badge active" }, "ACTIVE") : null),
            h("small", {}, `${ph.weeks} · ${ph.milestone} · ${s.done}/${s.total}`)),
          stackedBar(ph.id, true),
          h("span", { class: "pct" }, s.pct + "%")),
        h("div", { class: "phase-body" }, groups.map(g => [
          h("h3", {}, g),
          list.filter(t => t.group === g).map(t => {
            const st = statusOf(t);
            return h("button", { class: "trow", type: "button", style: `--c:var(--cat-${t.cat})`, onclick: () => openTask(t.id) },
              h("span", { class: "id" }, t.id),
              h("span", { class: "tag" }, t.cat),
              h("span", { class: `t${st === "done" ? " done" : ""}` }, t.title),
              avatar(S.members[t.owner], "sm"),
              h("span", { class: "pill", style: `--s:var(--st-${st})` }, h("span", { class: "sdot" }), STATUS[st].label));
          }),
        ])));
    }));
  }

  /* ---------------- task modal ---------------- */
  function openTask(id) {
    const t = S.tasks.find(x => x.id === id);
    if (!t) return;
    const m = S.members[t.owner];
    const ts = taskState(t);
    const tp = taskPrompt(t);
    const up = updatePrompt(t);
    $("#mContent").replaceChildren(
      h("p", { class: "eyebrow mono" }, `${t.id} · ${t.cat} · PHASE ${t.phase}`),
      h("h2", { id: "mTitle" }, t.title),
      h("dl", {},
        h("dt", {}, "المسؤول"), h("dd", {}, h("span", { style: `color:${m?.color};font-weight:600` }, m?.name || t.owner)),
        h("dt", {}, "الحالة"), h("dd", {}, h("span", { class: "pill", style: `--s:var(--st-${ts.status})` }, h("span", { class: "sdot" }), STATUS[ts.status].label)),
        h("dt", {}, "المرحلة"), h("dd", {}, `${PHASES[t.phase - 1].name} › `, h("span", { dir: "ltr" }, t.group)),
        h("dt", {}, "القسم"), h("dd", {}, CATS[t.cat]),
        ts.note ? [h("dt", {}, "ملاحظة"), h("dd", {}, ts.note)] : null,
        ts.updated_at ? [h("dt", {}, "آخر تحديث"), h("dd", {}, h("span", { class: "mono" }, ts.updated_at), ts.by && ts.by !== t.owner ? ` · بواسطة ${S.members[ts.by]?.name}` : "")] : null),
      h("h3", { style: "font-size:13px;color:var(--muted);margin:0 0 6px" }, "برومبت البدء بالمهمة"),
      h("pre", {}, tp),
      h("h3", { style: "font-size:13px;color:var(--muted);margin:0 0 6px" }, "برومبت تحديث الحالة"),
      h("pre", {}, up),
      h("div", { class: "form-actions" },
        h("button", { class: "btn primary small", type: "button", onclick: () => copy(tp) }, "نسخ برومبت البدء"),
        h("button", { class: "btn small", type: "button", onclick: () => copy(up) }, "نسخ برومبت التحديث"),
        h("a", { class: "btn small", href: ghBlob("docs/PROJECT_ROADMAP.md"), target: "_blank", rel: "noopener" }, "الخطة")));
    const dlg = $("#taskModal");
    if (typeof dlg.showModal === "function") { if (!dlg.open) dlg.showModal(); } else dlg.setAttribute("open", "");
  }

  /* ---------------- ideas ---------------- */
  function initIdeaForm() {
    $("#ideaAuthor").replaceChildren(...S.team.map(m => h("option", { value: m.id }, m.name)));
    $("#ideaCat").replaceChildren(...Object.entries(IDEA_CATS).map(([k, c]) => h("option", { value: k }, c.label)));

    const read = () => ({
      author: $("#ideaAuthor").value, category: $("#ideaCat").value,
      title: $("#ideaTitle").value.trim(), body: $("#ideaBody").value.trim(),
    });

    $("#ideaForm").addEventListener("submit", e => {
      e.preventDefault();
      const i = read();
      if (!i.title || !i.body) return;
      const meta = `<!-- idea: ${JSON.stringify({ author: i.author, category: i.category })} -->`;
      const body = `${meta}\n**صاحب الفكرة:** ${S.members[i.author]?.name}\n**النوع:** ${IDEA_CATS[i.category].label}\n\n${i.body}`;
      const url = `https://github.com/${REPO}/issues/new?` + new URLSearchParams({ title: `${IDEA_PREFIX} ${i.title}`, body, labels: "idea" });
      window.open(url, "_blank", "noopener");
      toast("انفتحت صفحة GitHub. اضغط Submit new issue");
    });

    $("#ideaCopy").addEventListener("click", () => {
      const i = read();
      if (!i.title) { $("#ideaTitle").focus(); return; }
      copy(`أنا ${S.members[i.author]?.name} (${i.author}). عندي فكرة للعبة، سجّلها حسب AGENTS.md §4.\n` +
        `النوع: ${i.category}\nالعنوان: ${i.title}\nالتفاصيل: ${i.body}`);
    });
  }

  async function loadIssues() {
    try {
      const res = await fetch(`https://api.github.com/repos/${REPO}/issues?state=all&per_page=100`, { headers: { Accept: "application/vnd.github+json" } });
      if (!res.ok) throw new Error(res.status);
      const all = await res.json();
      S.issues = all
        .filter(x => !x.pull_request && (x.title.startsWith(IDEA_PREFIX) || x.labels?.some(l => l.name === "idea")))
        .map(x => {
          let meta = {};
          const mm = /<!--\s*idea:\s*(\{.*?\})\s*-->/.exec(x.body || "");
          if (mm) { try { meta = JSON.parse(mm[1]); } catch { /* ignore */ } }
          const author = meta.author || S.team.find(m => m.github?.toLowerCase() === x.user?.login?.toLowerCase())?.id || x.user?.login;
          const body = (x.body || "").replace(/<!--[\s\S]*?-->/g, "").replace(/^\*\*(صاحب الفكرة|النوع):\*\*.*$/gm, "").trim();
          return {
            id: `#${x.number}`, date: x.created_at.slice(0, 10), author, category: IDEA_CATS[meta.category] ? meta.category : "other",
            status: x.state, title: x.title.replace(IDEA_PREFIX, "").trim(), body, url: x.html_url,
            votes: x.reactions?.["+1"] || 0, comments: x.comments || 0,
          };
        });
    } catch {
      S.issuesError = true;
    }
    renderIdeas();
  }

  function renderIdeas() {
    const all = [...S.issues, ...S.ideas.map(i => ({ ...i, url: null }))];
    const cat = S.ui.ideaCat;
    $("#ideaChips").replaceChildren(
      h("button", { class: "chip", type: "button", "aria-pressed": String(cat === "all"), onclick: () => { S.ui.ideaCat = "all"; saveUI(); renderIdeas(); } }, `الكل (${all.length})`),
      ...Object.entries(IDEA_CATS).map(([k, c]) => {
        const n = all.filter(i => i.category === k).length;
        return n ? h("button", {
          class: "chip", type: "button", style: `--c:${c.color}`, "aria-pressed": String(cat === k),
          onclick: () => { S.ui.ideaCat = cat === k ? "all" : k; saveUI(); renderIdeas(); },
        }, `${c.label} (${n})`) : null;
      }));

    const list = all.filter(i => cat === "all" || i.category === cat)
      .sort((a, b) => (b.votes || 0) - (a.votes || 0) || (b.date || "").localeCompare(a.date || ""));

    const nodes = list.map(i => {
      const m = S.members[i.author];
      const c = IDEA_CATS[i.category] || IDEA_CATS.other;
      return h("article", { class: "panel idea", style: `--c:${c.color}` },
        h("header", {},
          h("span", { class: "tagc" }, c.label),
          h("span", { class: "istatus" }, IDEA_STATUS[i.status] || i.status),
          h("span", { class: "mono", style: "margin-inline-start:auto" }, i.date)),
        h("h3", {}, i.title),
        h("p", {}, i.body),
        h("footer", {},
          m ? [avatar(m, "sm"), h("span", {}, m.name)] : h("span", {}, i.author === "gdd" ? "📄 وثيقة التصميم" : i.author),
          i.url ? [h("span", {}, `👍 ${i.votes}`), h("span", {}, `💬 ${i.comments}`), h("a", { href: i.url, target: "_blank", rel: "noopener" }, "ناقش وصوّت ←")] : null));
    });
    if (S.issuesError) nodes.unshift(h("div", { class: "panel empty", style: "grid-column:1/-1" }, "تعذّر تحميل أفكار GitHub Issues حالياً (حد الطلبات). الأفكار المحفوظة بالمستودع معروضة."));
    $("#ideas").replaceChildren(...(nodes.length ? nodes : [h("div", { class: "empty", style: "grid-column:1/-1" }, "ماكو أفكار بهذا القسم بعد.")]));
  }

  /* ---------------- prompts view ---------------- */
  function renderPrompts() {
    $("#promptCards").replaceChildren(...S.team.map(m => {
      const s = stats(S.tasks.filter(t => t.owner === m.id));
      const p = startPrompt(m);
      return h("article", { class: "panel prompt-card", style: `--c:${m.color}` },
        h("div", { class: "member-head" }, avatar(m), h("div", {}, h("h2", {}, m.name), h("span", { style: "color:var(--muted);font-size:12px" }, `${s.total} مهمة · ${s.pct}% مكتمل`))),
        h("p", { style: "margin:0;color:#c3ccd8;font-size:13px" }, m.role),
        h("pre", {}, p),
        h("div", { class: "actions" },
          h("button", { class: "btn primary small", type: "button", onclick: () => copy(p) }, "نسخ البرومبت"),
          h("a", { class: "btn small", href: ghBlob(m.prompt_file), target: "_blank", rel: "noopener" }, "كل برومبتات " + m.name),
          h("a", { class: "btn small", href: ghBlob(`data/progress/${m.id}.json`), target: "_blank", rel: "noopener" }, "ملف التقدم")));
    }));
  }

  /* ---------------- boot ---------------- */
  function setLive(ok, text) {
    const el = $("#liveStatus");
    el.classList.toggle("ok", ok);
    el.classList.toggle("err", !ok);
    el.querySelector("span").textContent = text;
  }

  function renderAll() {
    renderHome();
    renderTeam();
    renderBoard();
    renderRoadmap();
    renderPrompts();
    renderIdeas();
  }

  async function boot() {
    document.querySelectorAll("a[data-gh]").forEach(a => { a.href = ghBlob(a.getAttribute("href")); a.target = "_blank"; a.rel = "noopener"; });
    $("#phaseSel").replaceChildren(h("option", { value: "all" }, "كل المراحل"), ...PHASES.map(p => h("option", { value: String(p.id) }, `المرحلة ${p.id} — ${p.name}`)));
    $("#phaseSel").addEventListener("change", e => setUI({ phase: e.target.value }));
    let qt;
    $("#searchBox").addEventListener("input", e => { clearTimeout(qt); qt = setTimeout(() => setUI({ q: e.target.value }), 150); });
    $("#taskModal").addEventListener("click", e => { if (e.target === e.currentTarget) e.currentTarget.close(); });
    window.addEventListener("hashchange", route);
    route();

    try {
      const [team, tasks, ideas] = await Promise.all([getJSON("data/team.json"), getJSON("data/tasks.json"), getJSON("data/ideas.json").catch(() => ({ ideas: [] }))]);
      S.team = team.members;
      S.members = Object.fromEntries(S.team.map(m => [m.id, m]));
      S.tasks = tasks.tasks;
      S.ideas = ideas.ideas || [];
      const prog = await Promise.allSettled(S.team.map(m => getJSON(`data/progress/${m.id}.json`)));
      prog.forEach((r, i) => { S.progress[S.team[i].id] = r.status === "fulfilled" ? r.value : { tasks: {}, log: [] }; });

      initIdeaForm();
      renderAll();

      const last = Object.values(S.progress).map(p => p.updated_at || "").sort().pop();
      setLive(true, last ? `مباشر · آخر تحديث ${last}` : "مباشر");
      $("#dataStamp").textContent = `${S.tasks.length} مهمة · ${S.team.length} أعضاء${last ? " · " + last : ""}`;
      loadIssues();
    } catch (err) {
      console.error(err);
      setLive(false, "تعذّر تحميل البيانات");
      $("#teamStrip").replaceChildren(h("div", { class: "panel empty", style: "grid-column:1/-1" },
        "ما كدرنا نحمّل ملفات data/. افتح الموقع من GitHub Pages أو شغّل سيرفر محلي: python -m http.server"));
    }
  }

  boot();
})();
